// ============================================================================
// ONFI_apb: APB4 register wrapper around ONFI_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/ONFI.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/ONFI.md
// ============================================================================
module ONFI_apb #(
  parameter int TP    = 2,
  // WE# / RE# low and high time, clocks
  parameter int TWB   = 6,
  // tWB, clocks
  parameter int TWHR  = 8,
  // tWHR, clocks
  parameter int TADL  = 10,
  // tADL, clocks
  parameter int TRR   = 3,
  // tRR, clocks
  parameter int TBUSY = 2048,
  // R/B# low timeout, clocks (power of 2, above the waits)
  parameter int LW    = 12
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic ce_n,
  output logic cle,
  output logic ale,
  output logic we_n,
  output logic re_n,
  output logic [7:0] dq_o,
  output logic dq_oe,
  input logic [7:0] dq_i,
  input logic rb_n
);
  localparam logic [31:0] ID_VALUE = 32'h4F4E0200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_cmd_valid;
  logic          c_cmd_ready;
  logic [2:0]    c_cmd_op;
  logic [23:0]   c_cmd_row;
  logic [15:0]   c_cmd_col;
  logic [11:0]   c_cmd_len;
  logic          c_wr_valid;
  logic          c_wr_ready;
  logic [7:0]    c_wr_data;
  logic          c_rd_valid;
  logic          c_rd_ready;
  logic [7:0]    c_rd_data;
  logic          c_done;
  logic [7:0]    c_status;
  logic          c_ev_fail;
  logic          c_ev_timeout;
  ONFI_top #(.TP(TP), .TWB(TWB), .TWHR(TWHR), .TADL(TADL), .TRR(TRR), .TBUSY(TBUSY), .LW(LW)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cmd_valid(c_cmd_valid),
    .cmd_ready(c_cmd_ready),
    .cmd_op(c_cmd_op),
    .cmd_row(c_cmd_row),
    .cmd_col(c_cmd_col),
    .cmd_len(c_cmd_len),
    .wr_valid(c_wr_valid),
    .wr_ready(c_wr_ready),
    .wr_data(c_wr_data),
    .rd_valid(c_rd_valid),
    .rd_ready(c_rd_ready),
    .rd_data(c_rd_data),
    .done(c_done),
    .status(c_status),
    .ev_fail(c_ev_fail),
    .ev_timeout(c_ev_timeout),
    .ce_n(ce_n),
    .cle(cle),
    .ale(ale),
    .we_n(we_n),
    .re_n(re_n),
    .dq_o(dq_o),
    .dq_oe(dq_oe),
    .dq_i(dq_i),
    .rb_n(rb_n)
  );

  // ---------------- registers ----------------
  logic [7:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [26:0] h_CMD0;   // 12'h014 CMD0 holding register
  logic [27:0] h_CMD1;   // 12'h018 CMD1 holding register
  logic [7:0] h_WR;   // 12'h01C WR holding register
  logic [7:0] h_RD;   // 12'h020 RD holding register
  logic full_CMD;
  logic full_WR;
  logic avail_RD;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      h_CMD0 <= '0;
      h_CMD1 <= '0;
      h_WR <= '0;
      h_RD <= '0;
      full_CMD <= 1'b0;
      full_WR <= 1'b0;
      avail_RD <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[7:0] & wmask[7:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5] && !full_CMD) h_CMD0 <= (h_CMD0 & ~wmask[26:0]) | (PWDATA[26:0] & wmask[26:0]);
      if (wr && hit[6] && !full_CMD) h_CMD1 <= (h_CMD1 & ~wmask[27:0]) | (PWDATA[27:0] & wmask[27:0]);
      if (wr && hit[6] && !full_CMD) full_CMD <= 1'b1;
      else if (full_CMD && c_cmd_ready) full_CMD <= 1'b0;
      if (wr && hit[7] && !full_WR) h_WR <= (h_WR & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[7] && !full_WR) full_WR <= 1'b1;
      else if (full_WR && c_wr_ready) full_WR <= 1'b0;
      if (c_rd_valid && (!avail_RD || (rd && hit[8]))) begin
        h_RD[7:0] <= c_rd_data[7:0];
        avail_RD <= 1'b1;
      end else if (rd && hit[8]) avail_RD <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cmd_row[23:0] = h_CMD0[23:0];
  assign c_cmd_op[2:0] = h_CMD0[26:24];
  assign c_cmd_col[15:0] = h_CMD1[15:0];
  assign c_cmd_len[11:0] = h_CMD1[27:16];
  assign c_wr_data[7:0] = h_WR[7:0];
  assign c_cmd_valid = full_CMD;
  assign c_wr_valid = full_WR;
  assign c_rd_ready = ~avail_RD | (rd & hit[8]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_ev_fail;
    irq_set[2] = c_ev_timeout;
    irq_set[3] = full_CMD & c_cmd_ready;
    irq_set[4] = wr & (hit[5] | hit[6]) & full_CMD;
    irq_set[5] = full_WR & c_wr_ready;
    irq_set[6] = wr & (hit[7]) & full_WR;
    irq_set[7] = c_rd_valid & (~avail_RD | (rd & hit[8]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [2:0] flags = {avail_RD, full_WR, full_CMD};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(h_CMD0);
      10'd6: apb_rdata = 32'(h_CMD1);
      10'd7: apb_rdata = 32'(h_WR);
      10'd8: apb_rdata = 32'(h_RD);
      10'd9: apb_rdata = 32'({c_status});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
